package com.bank.spark.model;

// A join side: what Spark estimates vs the true size, and if the estimate is trustworthy.
public class JoinSide {
    private final String name;
    private final long estimatedBytes;   // what Catalyst thinks
    private final long actualBytes;        // the real size (post-filter)
    private final boolean statsTrustworthy;

    public JoinSide(String name, long estimatedBytes, long actualBytes, boolean statsTrustworthy) {
        this.name = name;
        this.estimatedBytes = estimatedBytes;
        this.actualBytes = actualBytes;
        this.statsTrustworthy = statsTrustworthy;
    }

    public String getName() { return name; }
    public long getEstimatedBytes() { return estimatedBytes; }
    public long getActualBytes() { return actualBytes; }
    public boolean isStatsTrustworthy() { return statsTrustworthy; }
}
