package com.bank.spark.service;

import com.bank.spark.model.JoinSide;

// Decides auto-broadcast vs explicit hint vs sort-merge.
public class BroadcastDecider {

    private final long threshold;

    public BroadcastDecider(long threshold) {
        this.threshold = threshold;
    }

    public String decide(JoinSide side) {
        boolean autoWouldBroadcast = side.getEstimatedBytes() <= threshold;
        boolean actuallySmall = side.getActualBytes() <= threshold;

        if (autoWouldBroadcast && side.isStatsTrustworthy()) {
            return "AUTO-BROADCAST: estimate " + mb(side.getEstimatedBytes()) + " <= threshold — no hint needed";
        }
        if (!autoWouldBroadcast && actuallySmall) {
            return "USE EXPLICIT broadcast() HINT: estimate " + mb(side.getEstimatedBytes())
                    + " is above threshold but real size is " + mb(side.getActualBytes()) + " (estimator blind)";
        }
        if (!actuallySmall) {
            return "DO NOT broadcast: real size " + mb(side.getActualBytes()) + " too large — would risk OOM; use sort-merge";
        }
        return "AUTO-BROADCAST likely, but verify plan (stats untrustworthy)";
    }

    private String mb(long bytes) { return (bytes / (1024 * 1024)) + " MB"; }
}
