package com.bank.spark;

import com.bank.spark.model.JoinSide;
import com.bank.spark.service.BroadcastDecider;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BroadcastThresholdDemo {

    private static final Logger log = Logger.getLogger(BroadcastThresholdDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        long tenMB = 10L * 1024 * 1024;
        BroadcastDecider decider = new BroadcastDecider(tenMB);

        List<JoinSide> sides = List.of(
                new JoinSide("branches (fresh stats)", 2L * 1024 * 1024, 2L * 1024 * 1024, true),
                new JoinSide("products (filtered to active)", 50L * 1024 * 1024, 3L * 1024 * 1024, true),
                new JoinSide("rawFiles (no stats)", 500L * 1024 * 1024, 1L * 1024 * 1024, false),
                new JoinSide("customers (genuinely large)", 800L * 1024 * 1024, 800L * 1024 * 1024, true)
        );

        for (JoinSide s : sides) {
            String decision = decider.decide(s);
            if (decision.startsWith("DO NOT")) {
                log.warning("[" + s.getName() + "] " + decision);
            } else if (decision.startsWith("USE EXPLICIT")) {
                log.info("[" + s.getName() + "] " + decision);
            } else {
                log.info("[" + s.getName() + "] " + decision);
            }
        }
    }
}

